// The client's nullifier scopes must equal the chain's, or every proof made for
// that op fails at broadcast as "ZK proof verification failed". The vectors
// are generated by the chain's own resolveNullifierScope over every default
// shielded op (x/shield/keeper/scope_vectors_test.go in the chain repo), read
// from the chain checkout beside this one or SPARKDREAM_CHAIN_REPO.
//
//   npm test

import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { test } from "node:test";
import type { ShieldedOpRegistration } from "@/types/shield";
import { resolveScope } from "./shieldScope";

interface ScopeVector {
  message_type_url: string;
  nullifier_domain: number;
  nullifier_scope_type: ShieldedOpRegistration["nullifier_scope_type"];
  scope_field_path: string;
  epoch_window: string;
  epoch: string;
  fields: Record<string, string>;
  scope: string;
}

const chainRepo = process.env.SPARKDREAM_CHAIN_REPO || path.resolve(process.cwd(), "../sparkdream");
const vectorsPath = path.join(chainRepo, "x/shield/keeper/testdata/scope_vectors.json");

function loadVectors(): ScopeVector[] {
  if (!fs.existsSync(vectorsPath)) {
    throw new Error(`no scope vectors at ${vectorsPath}: set SPARKDREAM_CHAIN_REPO to the chain repo checkout`);
  }
  return (JSON.parse(fs.readFileSync(vectorsPath, "utf8")) as { vectors: ScopeVector[] }).vectors;
}

function registration(v: ScopeVector): ShieldedOpRegistration {
  return {
    message_type_url: v.message_type_url,
    proof_domain: "PROOF_DOMAIN_TRUST_TREE",
    min_trust_level: 0,
    nullifier_domain: v.nullifier_domain,
    nullifier_scope_type: v.nullifier_scope_type,
    scope_field_path: v.scope_field_path,
    epoch_window: v.epoch_window,
    active: true,
    batch_mode: "SHIELD_BATCH_MODE_EITHER",
  };
}

const camel = (s: string) => s.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());

test("client nullifier scopes match the chain's for every default op", () => {
  const vectors = loadVectors();
  assert.ok(vectors.length > 0, "the vectors file is empty");
  for (const v of vectors) {
    const what = `${v.message_type_url} epoch=${v.epoch} fields=${JSON.stringify(v.fields)}`;
    // as the query returns them: snake_case, uint64 as decimal strings
    assert.equal(resolveScope(registration(v), v.fields, v.epoch), v.scope, what);
    // as the UI builds inner messages for cosmjs: camelCase, uint64 as bigint
    const inner = Object.fromEntries(Object.entries(v.fields).map(([k, x]) => [camel(k), BigInt(x)]));
    assert.equal(resolveScope(registration(v), inner, v.epoch), v.scope, `${what} (camelCase)`);
  }
});

test("an omitted epoch_window means one epoch per scope", () => {
  const v = loadVectors().find((x) => x.nullifier_scope_type === "NULLIFIER_SCOPE_EPOCH" && x.epoch_window === "0");
  assert.ok(v, "no EPOCH vector with epoch_window 0");
  const reg = registration(v);
  delete reg.epoch_window;
  assert.equal(resolveScope(reg, {}, v.epoch), v.scope);
});
